import 'dart:convert';import '../config.dart';import '../models/billing.dart';import 'authenticated_http_client.dart';class BillingService {final _http=AuthenticatedHttpClient();Future<List<BillingModule>> modules()async{final r=await _http.get(Uri.parse('${AppConfig.apiBaseUrl}/billing/modules'));if(r.statusCode!=200)throw Exception(r.body);return (jsonDecode(r.body) as List).map((e)=>BillingModule.fromJson(e)).toList();}Future<List<TenantEntitlement>> entitlements(String tenant)async{final r=await _http.get(Uri.parse('${AppConfig.apiBaseUrl}/billing/tenants/$tenant/entitlements'));if(r.statusCode!=200)throw Exception(r.body);return (jsonDecode(r.body) as List).map((e)=>TenantEntitlement.fromJson(e)).toList();}Future<void> setEntitlement(String tenant,String module,bool enabled)async{final r=await _http.put(Uri.parse('${AppConfig.apiBaseUrl}/billing/tenants/$tenant/entitlements'),headers:{'Content-Type':'application/json'},body:jsonEncode({'moduleCode':module,'enabled':enabled}));if(r.statusCode<200||r.statusCode>=300)throw Exception(r.body);}}